+                for (int k_block = 0; k_block < n; k_block += BLOCK_K) {
+                    int k_max = std::min(n, k_block + BLOCK_K);
+                    for (int j_block = 0; j_block < n; j_block += BLOCK_N) {
+                        int j_max = std::min(n, j_block + BLOCK_N);
